// Compare the browser model with reference cases generated by production C#.
// No browser, network, or npm packages are needed for this check.
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const root = path.resolve(__dirname, '..');
const fixturePath = process.argv[2] || path.join(root, 'artifacts', 'visualizer-reference-cases.json');
const fragmentPath = process.argv[3] || path.join(root, 'tools', 'visualizer', 'comparison.fragment.html');
const source = fs.readFileSync(fragmentPath, 'utf8');
const scripts = [...source.matchAll(/<script(?:\s[^>]*)?>([\s\S]*?)<\/script>/g)].map(match => match[1]);
scripts.forEach((script, index) => new vm.Script(script, { filename: `visualizer-script-${index}` }));
const context = vm.createContext({});
vm.runInContext(scripts[0], context);
if (typeof context.JoystickCompare?.remapper !== 'function') throw Error('Remapper model is missing.');

const data = JSON.parse(fs.readFileSync(fixturePath, 'utf8'));
const totals = {};
let maxFloatError = 0, maxStickError = 0, roundingCases = 0;
for (const profile of data.profiles) {
  const mode = profile.settings.mappingMode;
  for (const sample of profile.cases) {
    const actual = context.JoystickCompare.remapper(...sample.input, profile.settings);
    // Legacy ApplyStick may exceed unit axes; both virtual output and the
    // visualizer clamp them at encoding. Compare the same observable values.
    const expected = sample.output.map(value => Math.max(-1, Math.min(1, value)));
    const floatError = Math.max(...actual.out.map((value, index) => Math.abs(value - expected[index])));
    const stickError = Math.max(...actual.stick.map((value, index) => Math.abs(value - sample.stick[index])));
    maxFloatError = Math.max(maxFloatError, floatError);
    maxStickError = Math.max(maxStickError, stickError);
    // Trigonometric library rounding can straddle a signed-16 truncation edge.
    if (!Number.isFinite(floatError) || floatError > 1e-12 || !Number.isFinite(stickError) || stickError > 1)
      throw Error(JSON.stringify({ profile: profile.name, input: sample.input, expected, actual, floatError, stickError }));
    if (stickError) roundingCases++;
    totals[mode] = (totals[mode] || 0) + 1;
  }
}
for (const mode of ['Radial', 'Angular', 'Axial'])
  if (!totals[mode]) throw Error(`No reference cases for ${mode}.`);
console.log(JSON.stringify({ totals, maxFloatError, maxStickError, roundingCases }, null, 2));
